#!/usr/bin/env python3
"""Generate AI Job Impact HTML Report from data.csv"""

import pandas as pd
import numpy as np
import json
from datetime import datetime

df = pd.read_csv('/app/benchmark/data.csv')
df['survived'] = df['job_survival_class'] >= 1
df['top_surv'] = df['job_survival_class'] == 2

# ── Pre-compute all aggregations ──────────────────────────────────────────────

# Risk by job title
risk_by_title = df.groupby('job_title')['ai_risk_score'].mean().sort_values(ascending=False)

# Risk by country
risk_by_country = df.groupby('country')['ai_risk_score'].mean().sort_values(ascending=False)

# Risk over years
risk_by_year = df.groupby('year')['ai_risk_score'].mean()

# Median salary by year
salary_by_year = df.groupby('year')['salary'].median()

# Job survival rate by year
survival_by_year = df.groupby('year')['survived'].mean() * 100

# Strong survival (class=2) rate by year
strong_surv_by_year = df.groupby('year')['top_surv'].mean() * 100

# Total job openings by year
openings_by_year = df.groupby('year')['job_openings'].sum() / 1e6  # millions

# Skill demand (all years)
skill_demand_all = df.groupby('primary_skill')['skill_demand_score'].mean().sort_values(ascending=False)

# Skill demand 2015 vs 2035
skill_2015 = df[df['year'] == 2015].groupby('primary_skill')['skill_demand_score'].mean()
skill_2035 = df[df['year'] == 2035].groupby('primary_skill')['skill_demand_score'].mean()

# Median salary by country
sal_by_country = df.groupby('country')['salary'].median().sort_values(ascending=False)

# Median salary by job title
sal_by_title = df.groupby('job_title')['salary'].median().sort_values(ascending=False)

# Median salary by experience level
sal_by_exp = df.groupby('experience_level')['salary'].median()

# Median salary by risk category
sal_by_risk_cat = df.groupby('ai_risk_category')['salary'].median()

# Survival by country
surv_by_country = df.groupby('country')['survived'].mean() * 100

# Survival class avg by job title
surv_by_title = df.groupby('job_title')['job_survival_class'].mean().sort_values(ascending=False)

# Risk category counts
risk_cat_counts = df['ai_risk_category'].value_counts()

# Survival class counts
surv_class_counts = df['job_survival_class'].value_counts().sort_index()

# Country salary over selected years
sal_country_yr = df[df['year'].isin([2015, 2020, 2025, 2030, 2035])].groupby(['year', 'country'])['salary'].median().unstack()

# Skill demand over selected years
skill_yr = df[df['year'].isin([2015, 2020, 2025, 2030, 2035])].groupby(['year', 'primary_skill'])['skill_demand_score'].mean().unstack()

# Risk by role over years
risky_roles = ['Business Analyst', 'Data Analyst', 'Software Engineer', 'AI Researcher', 'ML Engineer']
risk_role_yr = df[df['job_title'].isin(risky_roles)].groupby(['year', 'job_title'])['ai_risk_score'].mean().unstack()

# Total records
n_records = len(df)
n_countries = df['country'].nunique()
n_roles = df['job_title'].nunique()
n_skills = df['primary_skill'].nunique()

# Key headline numbers
overall_avg_risk = df['ai_risk_score'].mean()
pct_high_risk = (df['ai_risk_category'] == 'High Risk').mean() * 100
pct_survived = df['survived'].mean() * 100
median_salary_overall = df['salary'].median()
median_salary_2035 = df[df['year'] == 2035]['salary'].median()
median_salary_2015 = df[df['year'] == 2015]['salary'].median()
salary_growth_pct = (median_salary_2035 - median_salary_2015) / median_salary_2015 * 100

risk_2015 = risk_by_year[2015]
risk_2035 = risk_by_year[2035]
risk_growth_pct = (risk_2035 - risk_2015) / risk_2015 * 100

# ── Helper: serialize series/lists to JSON ─────────────────────────────────────
def js(x):
    if isinstance(x, (pd.Series, pd.DataFrame)):
        return json.dumps(x.tolist())
    return json.dumps(x)

def js_keys(x):
    if isinstance(x, pd.Series):
        return json.dumps([str(k) for k in x.index.tolist()])
    return json.dumps([str(k) for k in x])

years_list = sorted(df['year'].unique().tolist())
COLORS = {
    'primary': '#1e40af',
    'secondary': '#0ea5e9',
    'accent': '#f59e0b',
    'danger': '#dc2626',
    'success': '#16a34a',
    'muted': '#64748b',
    'bg': '#f8fafc',
    'card': '#ffffff',
    'border': '#e2e8f0',
    'text': '#0f172a',
    'text2': '#475569',
}

ROLE_COLORS = {
    'Business Analyst': '#dc2626',
    'Data Analyst': '#f97316',
    'Software Engineer': '#eab308',
    'Product Manager': '#84cc16',
    'Cloud Engineer': '#22c55e',
    'Data Scientist': '#06b6d4',
    'DevOps Engineer': '#3b82f6',
    'ML Engineer': '#8b5cf6',
    'Cybersecurity Analyst': '#ec4899',
    'AI Researcher': '#14b8a6',
}

COUNTRY_COLORS = ['#1e40af', '#0ea5e9', '#059669', '#d97706', '#7c3aed', '#dc2626']

# ── Build chart datasets ───────────────────────────────────────────────────────

# Chart 1: AI Risk Score over time
c1_labels = js(years_list)
c1_data = js([round(risk_by_year[y], 4) for y in years_list])

# Chart 2: Risk by job title (horizontal bar)
c2_labels = js(risk_by_title.index.tolist())
c2_data = js([round(v, 4) for v in risk_by_title.values])
c2_colors = json.dumps([ROLE_COLORS.get(t, '#64748b') for t in risk_by_title.index])

# Chart 3: Median Salary by Year
c3_labels = js(years_list)
c3_data = js([round(salary_by_year[y], 2) for y in years_list])

# Chart 4: Salary by Country (bar)
c4_labels = js(sal_by_country.index.tolist())
c4_data = js([round(v, 2) for v in sal_by_country.values])

# Chart 5: Salary vs Risk category (grouped)
c5_cats = ['Low Risk', 'Medium Risk', 'High Risk']
c5_data = js([round(sal_by_risk_cat.get(c, 0), 2) for c in c5_cats])

# Chart 6: Job Survival Rate over time
c6_labels = js(years_list)
c6_data = js([round(survival_by_year[y], 2) for y in years_list])
c6_data2 = js([round(strong_surv_by_year[y], 2) for y in years_list])

# Chart 7: Job Openings over time (millions)
c7_labels = js(years_list)
c7_data = js([round(openings_by_year[y], 3) for y in years_list])

# Chart 8: Skill demand comparison 2015 vs 2035
skills_sorted = skill_demand_all.index.tolist()
c8_labels = js(skills_sorted)
c8_2015 = js([round(skill_2015.get(s, 0), 2) for s in skills_sorted])
c8_2035 = js([round(skill_2035.get(s, 0), 2) for s in skills_sorted])

# Chart 9: Risk category distribution (doughnut)
c9_labels = js(['Low Risk', 'Medium Risk', 'High Risk'])
c9_data = js([int(risk_cat_counts.get(c, 0)) for c in ['Low Risk', 'Medium Risk', 'High Risk']])

# Chart 10: Salary by experience level
c10_labels = js(['Entry', 'Mid', 'Senior'])
c10_data = js([round(sal_by_exp.get(l, 0), 2) for l in ['Entry', 'Mid', 'Senior']])

# Chart 11: Survival class by job title
c11_labels = js(surv_by_title.index.tolist())
c11_data = js([round(v, 3) for v in surv_by_title.values])
c11_colors = json.dumps([ROLE_COLORS.get(t, '#64748b') for t in surv_by_title.index])

# Chart 12: Risk over time by role (line, 5 roles)
c12_labels = js(years_list)
c12_datasets = []
for role in risky_roles:
    color = ROLE_COLORS.get(role, '#64748b')
    vals = [round(risk_role_yr[role].get(y, None) or 0, 4) for y in years_list]
    c12_datasets.append({
        'label': role,
        'data': vals,
        'borderColor': color,
        'backgroundColor': color + '22',
        'fill': False,
        'tension': 0.3,
        'borderWidth': 2,
        'pointRadius': 2,
    })
c12_datasets_js = json.dumps(c12_datasets)

# Chart 13: Country salary trend (line multi)
c13_labels = js(years_list)
countries = sal_by_country.index.tolist()
c13_datasets = []
for i, country in enumerate(countries):
    color = COUNTRY_COLORS[i % len(COUNTRY_COLORS)]
    vals = [round(df[(df['year'] == y) & (df['country'] == country)]['salary'].median() or 0, 2) for y in years_list]
    c13_datasets.append({
        'label': country,
        'data': vals,
        'borderColor': color,
        'backgroundColor': color + '22',
        'fill': False,
        'tension': 0.3,
        'borderWidth': 2,
        'pointRadius': 2,
    })
c13_datasets_js = json.dumps(c13_datasets)

# Chart 14: Survival by country
c14_labels = js(surv_by_country.sort_values(ascending=False).index.tolist())
c14_data = js([round(v, 2) for v in surv_by_country.sort_values(ascending=False).values])

# Build table: top roles by combined metrics
role_table = pd.DataFrame({
    'Avg AI Risk': risk_by_title.round(3),
    'Median Salary (USD)': sal_by_title.round(0).astype(int),
    'Avg Survival Score': surv_by_title.round(3),
}).sort_values('Avg AI Risk', ascending=False)

def color_risk(v):
    if v >= 0.6: return '#fee2e2'
    if v >= 0.35: return '#fef3c7'
    return '#dcfce7'

def risk_badge(v):
    if v >= 0.6: return f'<span style="background:#dc2626;color:#fff;padding:2px 8px;border-radius:12px;font-size:11px;font-weight:600;">High</span>'
    if v >= 0.35: return f'<span style="background:#d97706;color:#fff;padding:2px 8px;border-radius:12px;font-size:11px;font-weight:600;">Medium</span>'
    return f'<span style="background:#16a34a;color:#fff;padding:2px 8px;border-radius:12px;font-size:11px;font-weight:600;">Low</span>'

def surv_badge(v):
    if v >= 1.6: return f'<span style="background:#16a34a;color:#fff;padding:2px 8px;border-radius:12px;font-size:11px;font-weight:600;">Strong</span>'
    if v >= 1.0: return f'<span style="background:#0ea5e9;color:#fff;padding:2px 8px;border-radius:12px;font-size:11px;font-weight:600;">Moderate</span>'
    return f'<span style="background:#dc2626;color:#fff;padding:2px 8px;border-radius:12px;font-size:11px;font-weight:600;">At Risk</span>'

role_rows = ''
for title, row in role_table.iterrows():
    role_rows += f'''<tr>
        <td style="font-weight:600;color:#0f172a;">{title}</td>
        <td style="text-align:center;">{risk_badge(row["Avg AI Risk"])} <span style="color:#64748b;font-size:12px;margin-left:4px;">{row["Avg AI Risk"]:.3f}</span></td>
        <td style="text-align:right;font-weight:600;">${row["Median Salary (USD)"]:,}</td>
        <td style="text-align:center;">{surv_badge(row["Avg Survival Score"])} <span style="color:#64748b;font-size:12px;margin-left:4px;">{row["Avg Survival Score"]:.3f}</span></td>
    </tr>'''

# Skill table
skill_table_rows = ''
for skill in skills_sorted:
    d2015 = skill_2015.get(skill, 0)
    d2035 = skill_2035.get(skill, 0)
    change = d2035 - d2015
    arrow = '▲' if change > 0 else '▼'
    arrow_color = '#16a34a' if change > 0 else '#dc2626'
    skill_table_rows += f'''<tr>
        <td style="font-weight:600;">{skill}</td>
        <td style="text-align:right;">{d2015:.1f}</td>
        <td style="text-align:right;">{d2035:.1f}</td>
        <td style="text-align:right;color:{arrow_color};font-weight:700;">{arrow} {abs(change):.1f}</td>
    </tr>'''

# Country table
country_rows = ''
for country in sal_by_country.index:
    med_sal = sal_by_country[country]
    avg_risk = risk_by_country[country]
    surv_rate = surv_by_country[country]
    country_rows += f'''<tr>
        <td style="font-weight:600;">{country}</td>
        <td style="text-align:right;font-weight:600;">${med_sal:,.0f}</td>
        <td style="text-align:center;">{risk_badge(avg_risk)} <span style="color:#64748b;font-size:12px;">{avg_risk:.3f}</span></td>
        <td style="text-align:right;font-weight:600;">{surv_rate:.1f}%</td>
    </tr>'''

# ── Build final HTML ──────────────────────────────────────────────────────────

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AI Impact on the Global Job Market: Risk, Salary &amp; Skills Trend Analysis 2015–2035</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --primary: #1e40af;
    --secondary: #0ea5e9;
    --accent: #f59e0b;
    --danger: #dc2626;
    --success: #16a34a;
    --muted: #64748b;
    --bg: #f1f5f9;
    --card: #ffffff;
    --border: #e2e8f0;
    --text: #0f172a;
    --text2: #475569;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{ font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; background: var(--bg); color: var(--text); line-height: 1.6; }}
  .page-header {{ background: linear-gradient(135deg, #0f172a 0%, #1e3a8a 50%, #1e40af 100%); color: #fff; padding: 56px 48px 48px; }}
  .page-header .label {{ font-size: 12px; letter-spacing: 2px; text-transform: uppercase; color: #93c5fd; font-weight: 600; margin-bottom: 12px; }}
  .page-header h1 {{ font-size: 32px; font-weight: 800; line-height: 1.2; max-width: 700px; margin-bottom: 16px; }}
  .page-header .subtitle {{ font-size: 16px; color: #bfdbfe; max-width: 680px; }}
  .page-header .meta {{ display: flex; gap: 32px; margin-top: 32px; flex-wrap: wrap; }}
  .page-header .meta-item {{ font-size: 13px; color: #93c5fd; }}
  .page-header .meta-item strong {{ display: block; font-size: 22px; color: #fff; font-weight: 700; }}
  .nav {{ background: #0f172a; padding: 0 48px; display: flex; gap: 0; overflow-x: auto; }}
  .nav a {{ color: #94a3b8; text-decoration: none; font-size: 13px; font-weight: 500; padding: 14px 16px; border-bottom: 3px solid transparent; white-space: nowrap; transition: all 0.2s; }}
  .nav a:hover {{ color: #fff; border-bottom-color: #3b82f6; }}
  .container {{ max-width: 1280px; margin: 0 auto; padding: 40px 48px; }}
  .section {{ margin-bottom: 56px; }}
  .section-header {{ display: flex; align-items: flex-start; gap: 16px; margin-bottom: 28px; }}
  .section-num {{ background: var(--primary); color: #fff; width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 700; flex-shrink: 0; margin-top: 2px; }}
  .section-header h2 {{ font-size: 22px; font-weight: 700; color: var(--text); }}
  .section-header p {{ font-size: 14px; color: var(--text2); margin-top: 4px; }}
  .card {{ background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 24px; }}
  .card-title {{ font-size: 13px; font-weight: 600; color: var(--text2); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 16px; }}
  .grid-2 {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}
  .grid-3 {{ display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }}
  .grid-4 {{ display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }}
  .kpi-grid {{ display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; margin-bottom: 32px; }}
  .kpi {{ background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 20px; }}
  .kpi .kpi-label {{ font-size: 12px; color: var(--muted); font-weight: 500; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; }}
  .kpi .kpi-value {{ font-size: 26px; font-weight: 800; color: var(--text); line-height: 1; }}
  .kpi .kpi-sub {{ font-size: 12px; color: var(--text2); margin-top: 6px; }}
  .kpi .kpi-change {{ font-size: 13px; font-weight: 600; margin-top: 6px; }}
  .kpi .kpi-change.up {{ color: var(--success); }}
  .kpi .kpi-change.down {{ color: var(--danger); }}
  .kpi .kpi-change.warn {{ color: #d97706; }}
  .chart-wrap {{ position: relative; height: 280px; }}
  .chart-wrap.tall {{ height: 360px; }}
  .chart-wrap.short {{ height: 220px; }}
  .findings-box {{ background: #eff6ff; border-left: 4px solid #2563eb; border-radius: 0 8px 8px 0; padding: 16px 20px; margin-top: 20px; }}
  .findings-box h4 {{ font-size: 13px; font-weight: 700; color: #1e40af; margin-bottom: 8px; text-transform: uppercase; letter-spacing: 0.5px; }}
  .findings-box ul {{ list-style: none; padding: 0; }}
  .findings-box ul li {{ font-size: 13px; color: #1e3a8a; padding: 3px 0; padding-left: 16px; position: relative; }}
  .findings-box ul li::before {{ content: "→"; position: absolute; left: 0; color: #3b82f6; font-weight: 700; }}
  .exec-box {{ background: linear-gradient(135deg, #f0f9ff 0%, #e0f2fe 100%); border: 1px solid #bae6fd; border-radius: 12px; padding: 28px; margin-bottom: 32px; }}
  .exec-box h3 {{ font-size: 16px; font-weight: 700; color: #0369a1; margin-bottom: 16px; }}
  .exec-insights {{ display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }}
  .exec-insight {{ background: #fff; border: 1px solid #bae6fd; border-radius: 8px; padding: 16px; }}
  .exec-insight .insight-num {{ font-size: 11px; font-weight: 700; color: #0369a1; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 6px; }}
  .exec-insight .insight-text {{ font-size: 14px; color: #0f172a; line-height: 1.5; }}
  .exec-insight .insight-text strong {{ color: #0369a1; }}
  table {{ width: 100%; border-collapse: collapse; font-size: 13px; }}
  th {{ background: #f8fafc; color: var(--text2); font-weight: 600; padding: 10px 14px; text-align: left; border-bottom: 2px solid var(--border); font-size: 12px; text-transform: uppercase; letter-spacing: 0.5px; }}
  td {{ padding: 10px 14px; border-bottom: 1px solid var(--border); color: var(--text); }}
  tr:last-child td {{ border-bottom: none; }}
  tr:hover td {{ background: #f8fafc; }}
  .rec-grid {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}
  .rec-card {{ background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 24px; border-top: 4px solid; }}
  .rec-card.priority-1 {{ border-top-color: #dc2626; }}
  .rec-card.priority-2 {{ border-top-color: #d97706; }}
  .rec-card.priority-3 {{ border-top-color: #2563eb; }}
  .rec-card.priority-4 {{ border-top-color: #16a34a; }}
  .rec-priority {{ font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 8px; }}
  .priority-1 .rec-priority {{ color: #dc2626; }}
  .priority-2 .rec-priority {{ color: #d97706; }}
  .priority-3 .rec-priority {{ color: #2563eb; }}
  .priority-4 .rec-priority {{ color: #16a34a; }}
  .rec-card h3 {{ font-size: 16px; font-weight: 700; color: var(--text); margin-bottom: 10px; }}
  .rec-card p {{ font-size: 13px; color: var(--text2); line-height: 1.6; margin-bottom: 12px; }}
  .rec-card .data-link {{ font-size: 12px; color: var(--muted); background: #f8fafc; border: 1px solid var(--border); border-radius: 6px; padding: 6px 10px; font-style: italic; }}
  .footer {{ background: #0f172a; color: #94a3b8; padding: 32px 48px; font-size: 12px; margin-top: 48px; }}
  .footer strong {{ color: #e2e8f0; }}
  .disclaimer {{ background: #fefce8; border: 1px solid #fde68a; border-radius: 8px; padding: 12px 16px; font-size: 12px; color: #92400e; margin-top: 16px; }}
  .span-2 {{ grid-column: span 2; }}
  @media (max-width: 900px) {{
    .grid-2, .grid-3, .grid-4, .kpi-grid, .exec-insights, .rec-grid {{ grid-template-columns: 1fr; }}
    .container {{ padding: 24px 20px; }}
    .page-header {{ padding: 32px 20px; }}
    .nav {{ padding: 0 20px; }}
  }}
</style>
</head>
<body>

<!-- ── PAGE HEADER ── -->
<div class="page-header">
  <div class="label">Trend Analysis Report &bull; 2015–2035</div>
  <h1>AI Impact on the Global Job Market: Risk, Salary &amp; Skills Trend Analysis</h1>
  <p class="subtitle">A comprehensive analysis of how AI automation risk, salary dynamics, skill demand, and job survival prospects are evolving across roles, countries, and experience levels.</p>
  <div class="meta">
    <div class="meta-item"><strong>{n_records:,}</strong> Data Records</div>
    <div class="meta-item"><strong>{n_countries}</strong> Countries</div>
    <div class="meta-item"><strong>{n_roles}</strong> Job Roles</div>
    <div class="meta-item"><strong>{n_skills}</strong> Primary Skills</div>
    <div class="meta-item"><strong>2015–2035</strong> Time Horizon</div>
    <div class="meta-item"><strong>Generated</strong> {datetime.now().strftime('%B %d, %Y')}</div>
  </div>
</div>

<!-- ── NAV ── -->
<nav class="nav">
  <a href="#executive-overview">Executive Overview</a>
  <a href="#automation-risk">Automation Risk Landscape</a>
  <a href="#salary-trends">Salary Trends</a>
  <a href="#skills-demand">Skills Demand</a>
  <a href="#job-survival">Job Survival Outlook</a>
  <a href="#recommendations">Strategic Recommendations</a>
</nav>

<div class="container">

<!-- ══════════════════════════════════════════════════════════ -->
<!-- SECTION 1: EXECUTIVE OVERVIEW                           -->
<!-- ══════════════════════════════════════════════════════════ -->
<div class="section" id="executive-overview">
  <div class="section-header">
    <div class="section-num">1</div>
    <div>
      <h2>Executive Overview</h2>
      <p>Critical findings and KPIs across the 2015–2035 AI-disruption horizon</p>
    </div>
  </div>

  <!-- KPI Row -->
  <div class="kpi-grid">
    <div class="kpi">
      <div class="kpi-label">Avg AI Risk Score</div>
      <div class="kpi-value">{overall_avg_risk:.2f}</div>
      <div class="kpi-sub">Scale 0–1 (all roles, all years)</div>
      <div class="kpi-change warn">▲ +{risk_growth_pct:.0f}% since 2015</div>
    </div>
    <div class="kpi">
      <div class="kpi-label">High-Risk Share</div>
      <div class="kpi-value">{pct_high_risk:.0f}%</div>
      <div class="kpi-sub">of all job-year records</div>
      <div class="kpi-change warn">Business &amp; Data Analysts most exposed</div>
    </div>
    <div class="kpi">
      <div class="kpi-label">Overall Survival Rate</div>
      <div class="kpi-value">{pct_survived:.0f}%</div>
      <div class="kpi-sub">Class ≥ 1 (moderate or strong)</div>
      <div class="kpi-change down">Declining toward 2035</div>
    </div>
    <div class="kpi">
      <div class="kpi-label">Median Salary (2035)</div>
      <div class="kpi-value">${median_salary_2035:,.0f}</div>
      <div class="kpi-sub">vs. ${median_salary_2015:,.0f} in 2015</div>
      <div class="kpi-change up">▲ +{salary_growth_pct:.0f}% nominal growth</div>
    </div>
    <div class="kpi">
      <div class="kpi-label">Risk–Salary Gap</div>
      <div class="kpi-value">$12.4K</div>
      <div class="kpi-sub">Low Risk median vs High Risk</div>
      <div class="kpi-change up">Low Risk pays 57% more</div>
    </div>
  </div>

  <!-- Executive Insights -->
  <div class="exec-box">
    <h3>&#9654; Five Critical Executive Takeaways</h3>
    <div class="exec-insights">
      <div class="exec-insight">
        <div class="insight-num">Finding 01 &bull; Automation Risk Is Accelerating</div>
        <div class="insight-text">The average AI risk score has risen from <strong>0.30 in 2015 to 0.51 by 2035</strong> — a 72% increase. Business Analysts (0.75) and Data Analysts (0.65) face existential automation threat. Organizations heavily staffed with these roles must act urgently.</div>
      </div>
      <div class="exec-insight">
        <div class="insight-num">Finding 02 &bull; High Risk = Low Pay</div>
        <div class="insight-text">Roles with high AI risk command <strong>significantly lower compensation</strong>: High-Risk jobs median at $21,683 vs. $34,105 for Low-Risk roles — a 57% premium for automation-resilient work. Salary is the market's forward signal of automation vulnerability.</div>
      </div>
      <div class="exec-insight">
        <div class="insight-num">Finding 03 &bull; AI/ML Roles Are Future-Safe</div>
        <div class="insight-text"><strong>AI Researchers (risk: 0.15) and ML Engineers (risk: 0.25)</strong> sit at the opposite end of the risk spectrum and rank #1 and #2 in survival prospects. Python and Deep Learning skills define this safety corridor — reskilling investment should prioritize these pathways.</div>
      </div>
      <div class="exec-insight">
        <div class="insight-num">Finding 04 &bull; Survival Rate Is Declining</div>
        <div class="insight-text">The proportion of job-years classified as "at risk" (class = 0) has risen from <strong>~9% in 2015 to ~16% by 2035</strong>. Strong survival (class = 2) is also declining from 46% to 36%. The window for proactive reskilling is narrowing — investment must begin now.</div>
      </div>
      <div class="exec-insight">
        <div class="insight-num">Finding 05 &bull; USA Leads; India Most Exposed</div>
        <div class="insight-text">US-based roles offer the highest median salary ($43,422) and the highest survival rate (93.8%). India presents the starkest risk: lowest salary ($12,448) and lowest survival rate (78.6%). Geographic portfolio diversification strategy must account for this structural gap.</div>
      </div>
    </div>
  </div>

  <!-- Overview chart: Risk over time -->
  <div class="grid-2">
    <div class="card">
      <div class="card-title">AI Risk Score Trend (2015–2035)</div>
      <div class="chart-wrap">
        <canvas id="chart1"></canvas>
      </div>
    </div>
    <div class="card">
      <div class="card-title">Risk Category Distribution (All Records)</div>
      <div class="chart-wrap">
        <canvas id="chart9"></canvas>
      </div>
    </div>
  </div>
</div>

<!-- ══════════════════════════════════════════════════════════ -->
<!-- SECTION 2: AUTOMATION RISK LANDSCAPE                    -->
<!-- ══════════════════════════════════════════════════════════ -->
<div class="section" id="automation-risk">
  <div class="section-header">
    <div class="section-num">2</div>
    <div>
      <h2>AI Automation Risk Landscape</h2>
      <p>Distribution of AI risk scores and risk categories across roles, countries, and experience levels</p>
    </div>
  </div>

  <div class="grid-2" style="margin-bottom:20px;">
    <div class="card">
      <div class="card-title">Average AI Risk Score by Job Title</div>
      <div class="chart-wrap tall">
        <canvas id="chart2"></canvas>
      </div>
    </div>
    <div class="card">
      <div class="card-title">AI Risk Trajectory by Role (2015–2035)</div>
      <div class="chart-wrap tall">
        <canvas id="chart12"></canvas>
      </div>
    </div>
  </div>

  <div class="card" style="margin-bottom:20px;">
    <div class="card-title">Role-by-Role Risk, Salary &amp; Survival Summary</div>
    <table>
      <thead>
        <tr>
          <th>Job Title</th>
          <th style="text-align:center;">Avg AI Risk</th>
          <th style="text-align:right;">Median Salary</th>
          <th style="text-align:center;">Avg Survival Class</th>
        </tr>
      </thead>
      <tbody>{role_rows}</tbody>
    </table>
  </div>

  <div class="grid-2">
    <div class="card">
      <div class="card-title">Avg AI Risk Score by Country</div>
      <div class="chart-wrap short">
        <canvas id="chartRiskCountry"></canvas>
      </div>
    </div>
    <div class="card">
      <div class="card-title">Risk by Experience Level</div>
      <div style="display:flex;flex-direction:column;gap:12px;margin-top:8px;">
        {"".join([
            f'<div><div style="display:flex;justify-content:space-between;margin-bottom:4px;"><span style="font-size:13px;font-weight:600;">{lv}</span><span style="font-size:13px;color:#475569;">{df[df["experience_level"]==lv]["ai_risk_score"].mean():.3f}</span></div><div style="background:#e2e8f0;border-radius:4px;height:10px;"><div style="background:#1e40af;border-radius:4px;height:10px;width:{df[df["experience_level"]==lv]["ai_risk_score"].mean()*100:.0f}%;"></div></div></div>'
            for lv in ['Entry', 'Mid', 'Senior']
        ])}
        <div class="disclaimer" style="margin-top:8px;">Risk scores are nearly uniform across experience levels (Entry: 0.396, Mid: 0.399, Senior: 0.393), indicating that AI automation risk is driven by <em>role type</em>, not seniority.</div>
      </div>
    </div>
  </div>

  <div class="findings-box" style="margin-top:20px;">
    <h4>Key Risk Findings</h4>
    <ul>
      <li>Business Analysts (0.75) and Data Analysts (0.65) carry the highest automation risk — their core tasks (reporting, data summarization, spreadsheet analysis) are prime AI targets</li>
      <li>AI Researchers (0.15) and ML Engineers (0.25) are the least exposed; they create the AI rather than compete with it</li>
      <li>Average risk has risen every 5-year period: 0.30 (2015) → 0.36 (2020) → 0.43 (2025) → 0.51 (2035)</li>
      <li>Geographic risk differences are minimal (India 0.401 to UK 0.393), confirming role type is the dominant risk driver</li>
      <li>Experience level does not meaningfully differentiate risk — automation affects tasks, not tenure</li>
    </ul>
  </div>
</div>

<!-- ══════════════════════════════════════════════════════════ -->
<!-- SECTION 3: SALARY TRENDS                                -->
<!-- ══════════════════════════════════════════════════════════ -->
<div class="section" id="salary-trends">
  <div class="section-header">
    <div class="section-num">3</div>
    <div>
      <h2>Salary Trends &amp; Segmentation</h2>
      <p>Compensation evolution by country, role, experience, and AI risk category</p>
    </div>
  </div>

  <div class="card" style="margin-bottom:20px;">
    <div class="card-title">Global Median Salary Trend (2015–2035)</div>
    <div class="chart-wrap tall">
      <canvas id="chart3"></canvas>
    </div>
  </div>

  <div class="grid-2" style="margin-bottom:20px;">
    <div class="card">
      <div class="card-title">Median Salary by Country (All Years)</div>
      <div class="chart-wrap">
        <canvas id="chart4"></canvas>
      </div>
    </div>
    <div class="card">
      <div class="card-title">Country Salary Trajectories (2015–2035)</div>
      <div class="chart-wrap">
        <canvas id="chart13"></canvas>
      </div>
    </div>
  </div>

  <div class="grid-2" style="margin-bottom:20px;">
    <div class="card">
      <div class="card-title">Median Salary by Experience Level</div>
      <div class="chart-wrap short">
        <canvas id="chart10"></canvas>
      </div>
      <div class="findings-box" style="margin-top:12px;">
        <h4>Experience Premium</h4>
        <ul>
          <li>Senior roles earn 2.1× more than Entry-level ($48,318 vs. $22,924)</li>
          <li>The Mid→Senior jump (+46%) exceeds the Entry→Mid jump (+44%)</li>
          <li>Seniority is a key lever for salary resilience, regardless of role</li>
        </ul>
      </div>
    </div>
    <div class="card">
      <div class="card-title">Median Salary by AI Risk Category — The Risk Premium</div>
      <div class="chart-wrap short">
        <canvas id="chart5"></canvas>
      </div>
      <div class="findings-box" style="margin-top:12px;">
        <h4>Risk–Salary Inverse Correlation</h4>
        <ul>
          <li>High-Risk roles: $21,683 median — 37% below the global median</li>
          <li>Low-Risk roles: $34,105 median — the market rewards automation resilience</li>
          <li>Medium-Risk roles: $34,710 median — nearly identical to Low-Risk, suggesting the market prices a binary high/non-high risk distinction</li>
        </ul>
      </div>
    </div>
  </div>

  <div class="card" style="margin-bottom:20px;">
    <div class="card-title">Country Salary Comparison: Key Milestones</div>
    <table>
      <thead>
        <tr>
          <th>Country</th>
          <th style="text-align:right;">Median Salary (All Years)</th>
          <th style="text-align:center;">Avg AI Risk</th>
          <th style="text-align:right;">Survival Rate</th>
        </tr>
      </thead>
      <tbody>{country_rows}</tbody>
    </table>
  </div>

  <div class="findings-box">
    <h4>Key Salary Findings</h4>
    <ul>
      <li>Global median salary grew from $24,247 (2015) to $36,763 (2035), a 52% nominal increase</li>
      <li>USA dominates with $43,422 median — 3.5× India's $12,448, reflecting both cost structures and role mix</li>
      <li>Education level shows minimal salary differentiation (Bachelor $31,569 vs. PhD $31,672), suggesting skills and experience outweigh credentials</li>
      <li>High AI risk roles earn 37% below the global median — the market is already pricing automation probability into compensation</li>
      <li>All countries show upward salary trajectories through 2035, with USA growth from $35,320 to $53,354 (+51%)</li>
    </ul>
  </div>
</div>

<!-- ══════════════════════════════════════════════════════════ -->
<!-- SECTION 4: SKILLS DEMAND                                -->
<!-- ══════════════════════════════════════════════════════════ -->
<div class="section" id="skills-demand">
  <div class="section-header">
    <div class="section-num">4</div>
    <div>
      <h2>Skills Demand &amp; Future-Proofing</h2>
      <p>Skill demand trajectories, AI risk correlation, and the competencies most likely to survive disruption</p>
    </div>
  </div>

  <div class="grid-2" style="margin-bottom:20px;">
    <div class="card">
      <div class="card-title">Skill Demand Score: 2015 vs. 2035 Comparison</div>
      <div class="chart-wrap tall">
        <canvas id="chart8"></canvas>
      </div>
    </div>
    <div class="card">
      <div class="card-title">Skill Change Table: 2015→2035</div>
      <table style="margin-top:8px;">
        <thead>
          <tr>
            <th>Skill</th>
            <th style="text-align:right;">2015 Score</th>
            <th style="text-align:right;">2035 Score</th>
            <th style="text-align:right;">Change</th>
          </tr>
        </thead>
        <tbody>{skill_table_rows}</tbody>
      </table>
      <div class="disclaimer" style="margin-top:12px;">Skill demand scores are relatively stable (range: 76–83), suggesting broad market demand but Python and Java gaining the most ground.</div>
    </div>
  </div>

  <div class="card" style="margin-bottom:20px;">
    <div class="card-title">Skill vs. Automation Risk vs. Survival — The Future-Proofing Matrix</div>
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:8px;">
      {"".join([f'''<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:16px;">
        <div style="font-size:14px;font-weight:700;color:#0f172a;margin-bottom:8px;">{skill}</div>
        <div style="font-size:12px;color:#475569;">Risk Role: {df[df["primary_skill"]==skill]["ai_risk_category"].mode()[0] if len(df[df["primary_skill"]==skill])>0 else "N/A"}</div>
        <div style="font-size:12px;color:#475569;">Avg Risk: {df[df["primary_skill"]==skill]["ai_risk_score"].mean():.3f}</div>
        <div style="font-size:12px;color:#475569;">Avg Survival: {df[df["primary_skill"]==skill]["job_survival_class"].mean():.2f}</div>
