#!/usr/bin/env python3
"""Generate AI Job Impact HTML Report from data.csv"""

import pandas as pd
import numpy as np
import json
from datetime import datetime

df = pd.read_csv('/app/benchmark/data.csv')
df['survived'] = df['job_survival_class'] >= 1
df['top_surv'] = df['job_survival_class'] == 2

# ── Pre-compute all aggregations ──────────────────────────────────────────────

# Risk by job title
risk_by_title = df.groupby('job_title')['ai_risk_score'].mean().sort_values(ascending=False)

# Risk by country
risk_by_country = df.groupby('country')['ai_risk_score'].mean().sort_values(ascending=False)

# Risk over years
risk_by_year = df.groupby('year')['ai_risk_score'].mean()

# Median salary by year
salary_by_year = df.groupby('year')['salary'].median()

# Job survival rate by year
survival_by_year = df.groupby('year')['survived'].mean() * 100

# Strong survival (class=2) rate by year
strong_surv_by_year = df.groupby('year')['top_surv'].mean() * 100

# Total job openings by year
openings_by_year = df.groupby('year')['job_openings'].sum() / 1e6  # millions

# Skill demand (all years)
skill_demand_all = df.groupby('primary_skill')['skill_demand_score'].mean().sort_values(ascending=False)

# Skill demand 2015 vs 2035
skill_2015 = df[df['year'] == 2015].groupby('primary_skill')['skill_demand_score'].mean()
skill_2035 = df[df['year'] == 2035].groupby('primary_skill')['skill_demand_score'].mean()

# Median salary by country
sal_by_country = df.groupby('country')['salary'].median().sort_values(ascending=False)

# Median salary by job title
sal_by_title = df.groupby('job_title')['salary'].median().sort_values(ascending=False)

# Median salary by experience level
sal_by_exp = df.groupby('experience_level')['salary'].median()

# Median salary by risk category
sal_by_risk_cat = df.groupby('ai_risk_category')['salary'].median()

# Survival by country
surv_by_country = df.groupby('country')['survived'].mean() * 100

# Survival class avg by job title
surv_by_title = df.groupby('job_title')['job_survival_class'].mean().sort_values(ascending=False)

# Risk category counts
risk_cat_counts = df['ai_risk_category'].value_counts()

# Survival class counts
surv_class_counts = df['job_survival_class'].value_counts().sort_index()

# Country salary over selected years
sal_country_yr = df[df['year'].isin([2015, 2020, 2025, 2030, 2035])].groupby(['year', 'country'])['salary'].median().unstack()

# Skill demand over selected years
skill_yr = df[df['year'].isin([2015, 2020, 2025, 2030, 2035])].groupby(['year', 'primary_skill'])['skill_demand_score'].mean().unstack()

# Risk by role over years
risky_roles = ['Business Analyst', 'Data Analyst', 'Software Engineer', 'AI Researcher', 'ML Engineer']
risk_role_yr = df[df['job_title'].isin(risky_roles)].groupby(['year', 'job_title'])['ai_risk_score'].mean().unstack()

# Total records
n_records = len(df)
n_countries = df['country'].nunique()
n_roles = df['job_title'].nunique()
n_skills = df['primary_skill'].nunique()

# Key headline numbers
overall_avg_risk = df['ai_risk_score'].mean()
pct_high_risk = (df['ai_risk_category'] == 'High Risk').mean() * 100
pct_survived = df['survived'].mean() * 100
median_salary_overall = df['salary'].median()
median_salary_2035 = df[df['year'] == 2035]['salary'].median()
median_salary_2015 = df[df['year'] == 2015]['salary'].median()
salary_growth_pct = (median_salary_2035 - median_salary_2015) / median_salary_2015 * 100

risk_2015 = risk_by_year[2015]
risk_2035 = risk_by_year[2035]
risk_growth_pct = (risk_2035 - risk_2015) / risk_2015 * 100

# ── Helper: serialize series/lists to JSON ─────────────────────────────────────
def js(x):
    if isinstance(x, (pd.Series, pd.DataFrame)):
        return json.dumps(x.tolist())
    return json.dumps(x)

def js_keys(x):
    if isinstance(x, pd.Series):
        return json.dumps([str(k) for k in x.index.tolist()])
    return json.dumps([str(k) for k in x])

years_list = sorted(df['year'].unique().tolist())
COLORS = {
    'primary': '#1e40af',
    'secondary': '#0ea5e9',
    'accent': '#f59e0b',
    'danger': '#dc2626',
    'success': '#16a34a',
    'muted': '#64748b',
    'bg': '#f8fafc',
    'card': '#ffffff',
    'border': '#e2e8f0',
    'text': '#0f172a',
    'text2': '#475569',
}

