    'Business Analyst': '#dc2626',
    'Data Analyst': '#f97316',
    'Software Engineer': '#eab308',
    'Product Manager': '#84cc16',
    'Cloud Engineer': '#22c55e',
    'Data Scientist': '#06b6d4',
    'DevOps Engineer': '#3b82f6',
    'ML Engineer': '#8b5cf6',
    'Cybersecurity Analyst': '#ec4899',
    'AI Researcher': '#14b8a6',
}

COUNTRY_COLORS = ['#1e40af', '#0ea5e9', '#059669', '#d97706', '#7c3aed', '#dc2626']

# ── Build chart datasets ───────────────────────────────────────────────────────

# Chart 1: AI Risk Score over time
c1_labels = js(years_list)
