c6_data2 = js([round(strong_surv_by_year[y], 2) for y in years_list])

# Chart 7: Job Openings over time (millions)
c7_labels = js(years_list)
c7_data = js([round(openings_by_year[y], 3) for y in years_list])

# Chart 8: Skill demand comparison 2015 vs 2035
skills_sorted = skill_demand_all.index.tolist()
c8_labels = js(skills_sorted)
c8_2015 = js([round(skill_2015.get(s, 0), 2) for s in skills_sorted])
c8_2035 = js([round(skill_2035.get(s, 0), 2) for s in skills_sorted])

# Chart 9: Risk category distribution (doughnut)
c9_labels = js(['Low Risk', 'Medium Risk', 'High Risk'])
c9_data = js([int(risk_cat_counts.get(c, 0)) for c in ['Low Risk', 'Medium Risk', 'High Risk']])

# Chart 10: Salary by experience level
c10_labels = js(['Entry', 'Mid', 'Senior'])
c10_data = js([round(sal_by_exp.get(l, 0), 2) for l in ['Entry', 'Mid', 'Senior']])

# Chart 11: Survival class by job title
c11_labels = js(surv_by_title.index.tolist())
c11_data = js([round(v, 3) for v in surv_by_title.values])
c11_colors = json.dumps([ROLE_COLORS.get(t, '#64748b') for t in surv_by_title.index])

# Chart 12: Risk over time by role (line, 5 roles)
c12_labels = js(years_list)
c12_datasets = []
for role in risky_roles:
    color = ROLE_COLORS.get(role, '#64748b')
    vals = [round(risk_role_yr[role].get(y, None) or 0, 4) for y in years_list]
    c12_datasets.append({
        'label': role,
        'data': vals,
        'borderColor': color,
        'backgroundColor': color + '22',
        'fill': False,
        'tension': 0.3,
        'borderWidth': 2,
